LynomiaCustomers:
query LynomiaCustomers($first: Int!, $query: String!) {
  customers(first: $first, query: $query) {
    nodes { id defaultEmailAddress { emailAddress } defaultPhoneNumber { phoneNumber } }
  }
}

LynomiaGuestOrders:
query LynomiaGuestOrders($first: Int!, $query: String!) {
  orders(first: $first, query: $query, sortKey: CREATED_AT, reverse: true) {
    nodes { id email customer { id } }
  }
}

LynomiaOrders:
query LynomiaOrders($first: Int!, $query: String!) {
  orders(first: $first, query: $query, sortKey: CREATED_AT, reverse: true) { nodes { id legacyResourceId name createdAt updatedAt cancelledAt email
displayFinancialStatus displayFulfillmentStatus subtotalLineItemsQuantity
currentTotalPriceSet { presentmentMoney { amount currencyCode } }
customer { id }
lineItems(first: 10) { nodes { name quantity discountedTotalSet { presentmentMoney { amount } } } }
fulfillments(first: 10) {
  status displayStatus trackingInfo(first: 5) { company number url }
}
 } }
}

LynomiaOrder:
query LynomiaOrder($id: ID!) { order(id: $id) { id legacyResourceId name createdAt updatedAt cancelledAt email
displayFinancialStatus displayFulfillmentStatus subtotalLineItemsQuantity
currentTotalPriceSet { presentmentMoney { amount currencyCode } }
customer { id }
lineItems(first: 10) { nodes { name quantity discountedTotalSet { presentmentMoney { amount } } } }
fulfillments(first: 10) {
  status displayStatus trackingInfo(first: 5) { company number url }
}
 } }
